  [['الكل','🔎',-1],...CATS.map((c,i)=>[c.n,c.ic,i])].forEach(([n,ic,i])=>{const b=document.createElement('button');b.textContent=ic;b.title=n;if(i===gcat)b.className='p';b.onclick=()=>{gcat=i;drawGal()};ch.appendChild(b)});
  $('gt').textContent=gcat<0?'كل الرموز':CATS[gcat].n;
  CATS.forEach((c,i)=>{if(gcat>=0&&gcat!==i)return;c.it.forEach(([cp,nm])=>{if(!q||nm.includes(q))g.appendChild(eBtn(cp,nm,true))})});
