/* ---------- split: replace each selected element by n x m equal pieces inside its own box ---------- */
const NAT=new Map(),propOf=o=>o.type!=='shape'||o.kind==='star'||o.kind==='hex';
const rhoOf=o=>o.type==='emoji'?1:o.type==='shape'?SIZE[o.kind][1]:(NAT.get(baseSrc(o))>0?NAT.get(baseSrc(o)):o.a);
function splitCells(q){const{w,h,n,m,gap}=q,cw=(w-(n-1)*gap)/n,ch=(h-(m-1)*gap)/m;if(cw<2||ch<2)return null;const out=[];
  if(!q.prop){for(let j=0;j<m;j++)for(let i=0;i<n;i++)out.push({x:-w/2+cw/2+i*(cw+gap),y:-h/2+ch/2+j*(ch+gap),w:cw,h:ch});return out}
  const pw=Math.min(cw,ch/q.rho),ph=pw*q.rho;if(pw<2||ph<2)return null;const gx=n>1?(w-n*pw)/(n-1):0,gy=m>1?(h-m*ph)/(m-1):0;
  for(let j=0;j<m;j++)for(let i=0;i<n;i++)out.push({x:n>1?-w/2+pw/2+i*(pw+gx):0,y:m>1?-h/2+ph/2+j*(ph+gy):0,w:pw,h:ph});return out}
const planFor=(o,n,m,gap)=>{const p=P(o);return splitCells({w:p.w,h:p.h,n,m:o.kind==='line'?1:m,gap,prop:propOf(o),rho:rhoOf(o)})};
async function openSp(){if(!SS.size)return;const L=selItems().filter(o=>o.type!=='text');
  await Promise.all(L.filter(o=>!o.type).map(async o=>{const s=baseSrc(o);if(NAT.has(s))return;const im=await load(s);if(im&&im.width>0&&im.height>0)NAT.set(s,im.height/im.width)}));
  $('sn1').value=2;$('sn2').value=2;$('spg').value=8;$('sgp').checked=false;$('sp').classList.remove('hide');spUpdate()}
function spUpdate(){const all=selItems(),L=all.filter(o=>o.type!=='text'),cl=v=>Math.max(1,Math.min(50,Math.floor(+v)||1)),n=cl($('sn1').value),m=cl($('sn2').value),gap=Math.max(0,+$('spg').value||0);
  $('stot').textContent=n*m;let bad='',tot=0;const msg=[];
  if(!L.length)msg.push('لا يوجد عنصر قابل للتقسيم (النصوص مستثناة).');else if(all.length>L.length)msg.push(`${all.length-L.length} نص مستثنى.`);
  const plans=L.map(o=>{const pl=planFor(o,n,m,gap),cnt=o.kind==='line'?n:n*m,cap=!o.type?20:100;tot+=cnt;if(!pl)bad=bad||'invalid';else if(cnt>cap)bad=bad||'cap';return pl});
  if(tot>400)bad=bad||'cap';
  if(bad==='invalid')msg.push('المسافة كبيرة جدًا بالنسبة لحجم العنصر.');if(bad==='cap')msg.push('تجاوزت الحد: 20 قطعة للصورة، و100 لغيرها، و400 في المجموع.');if(n*m===1&&L.length)msg.push('1×1 لا يغيّر شيئًا.');
  $('spw').textContent=msg.join(' ');$('spok').disabled=!L.length||!!bad||n*m===1;
  const c=$('spv'),x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);if(!L.length||!plans[0])return;
  const p=P(L[0]),mg=10,sc=Math.min((c.width-2*mg)/p.w,(c.height-2*mg)/p.h),ox=c.width/2,oy=c.height/2,pr=propOf(L[0]);
  x.save();x.setLineDash([4,3]);x.strokeStyle='#9ca3af';x.strokeRect(ox-p.w*sc/2,oy-p.h*sc/2,p.w*sc,p.h*sc);x.restore();
  plans[0].forEach(q=>{const rl=ox+(q.x-q.w/2)*sc,rt=oy+(q.y-q.h/2)*sc;x.fillStyle=pr?'rgba(124,58,237,.45)':'rgba(13,148,136,.5)';x.fillRect(rl,rt,q.w*sc,q.h*sc);x.strokeStyle=pr?'#6d28d9':'#0f766e';x.strokeRect(rl,rt,q.w*sc,q.h*sc)})}
function applySplit(){const cl=v=>Math.max(1,Math.min(50,Math.floor(+v)||1)),n=cl($('sn1').value),m=cl($('sn2').value),gap=Math.max(0,+$('spg').value||0),L=selItems().filter(o=>o.type!=='text');if(!L.length)return;
  let gn=items.reduce((a,o)=>Math.max(a,o.g||0),0);const ids=[],by=new Map();
  L.forEach(o=>{const pl=planFor(o,n,m,gap);if(!pl)return;const p=P(o),cs=Math.cos(o.r),sn=Math.sin(o.r),grp=$('sgp').checked?++gn:0;
    by.set(o.id,pl.map(q=>{const c=JSON.parse(JSON.stringify(o));c.id=uid++;if(grp)c.g=grp;else delete c.g;
      c.x=(p.cx+q.x*cs-q.y*sn)/W;c.y=(p.cy+q.x*sn+q.y*cs)/W;c.s=q.w/W;c.a=q.h/q.w;if(c.ef==='hand')c.sd=(Math.random()*1e9|0)+1;ids.push(c.id);return c}))});
  items=items.flatMap(o=>by.has(o.id)?by.get(o.id):[o]);setSel(ids);$('sp').classList.add('hide');render();toast(`تم التقسيم: ${ids.length} قطعة`)}
