/* ---------- dual controls: every number box gets a slider and every slider gets a number box (manual typing still works) ---------- */
const pairs=[];
function dualize(id,c,host){const a=$(id),isNum=a.type==='number',b=document.createElement('input');b.type=isNum?'range':'number';b.id=id+'_t';
  const rng=isNum?b:a,num=isNum?a:b,hmin=c.hmin??c.min,hmax=c.hmax??c.max;
  rng.min=c.min;rng.max=c.max;rng.step=c.step||1;num.min=hmin;num.max=hmax;num.step=c.step||1;
  if(host)host.appendChild(b);else{const w=document.createElement('span');w.className='dual';a.replaceWith(w);w.append(rng,num)}
  b.addEventListener('input',()=>{if(b.value==='')return;let v=+b.value;if(!isNum){if(v>+a.max)a.max=Math.min(hmax,v);v=Math.min(hmax,Math.max(hmin,v))}a.value=v;a.dispatchEvent(new Event('input',{bubbles:true}))});
  b.addEventListener('change',()=>{b.value=a.value});
  a.addEventListener('input',()=>{if(document.activeElement!==b)b.value=a.value});
  pairs.push({a,b,c,hmin,hmax})}
function syncPairs(){pairs.forEach(({a,b})=>{if(document.activeElement!==b&&b.value!==a.value)b.value=a.value})}
dualize('cw',{min:5,max:800,hmax:3000});dualize('ch',{min:5,max:1200,hmax:6000});dualize('cr',{min:0,max:360,hmin:-360,hmax:360,step:0.1});
dualize('co',{min:10,max:100});dualize('pw',{min:0,max:30,hmax:100});dualize('pr',{min:0,max:100,hmax:500});dualize('tz',{min:10,max:200,hmax:800});dualize('bwt',{min:80,max:200});
