function stepper(id){const el=$(id),w=document.createElement('span');w.className='stp';el.replaceWith(w);
  const mk=(t,d)=>{const b=document.createElement('button');b.type='button';b.textContent=t;b.title=d>0?'زيادة':'نقصان';let tm=0,iv=0;
    const go=()=>{const lo=el.min!==''?+el.min:-1e9,hi=el.max!==''?+el.max:1e9,st=+el.step||1;el.value=Math.max(lo,Math.min(hi,(+el.value||0)+d*st));el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}))};
    const stop=()=>{clearTimeout(tm);clearInterval(iv)};
    b.addEventListener('pointerdown',e=>{e.preventDefault();go();tm=setTimeout(()=>{iv=setInterval(go,90)},420)});
    ['pointerup','pointerleave','pointercancel'].forEach(t=>b.addEventListener(t,stop));return b};
  w.append(mk('−',-1),el,mk('+',1))}
